package com.tekwatt.telemetry.entity;import jakarta.persistence.*;import java.math.BigDecimal;import java.time.Instant;import java.util.UUID;@Entity@Table(name="telemetry_readings")public class TelemetryReading{@Id private UUID id;@Column(nullable=false)private UUID tenantId;@Column(nullable=false)private UUID chargerId;@Column(nullable=false)private UUID connectorId;private UUID sessionId;@Column(length=100)private String transactionId;@Column(nullable=false,length=100)private String measurand;@Column(nullable=false,precision=20,scale=6)private BigDecimal value;@Column(nullable=false,length=30)private String unit;@Column(length=30)private String phase;@Column(length=50)private String context;@Column(length=30)private String location;@Column(nullable=false)private Instant sampledAt;@Column(nullable=false,updatable=false)private Instant receivedAt;protected TelemetryReading(){}public TelemetryReading(UUID t,UUID c,UUID connector,UUID session,String tx,String measurand,BigDecimal value,String unit,String phase,String context,String location,Instant sampled){id=UUID.randomUUID();tenantId=t;chargerId=c;connectorId=connector;sessionId=session;transactionId=tx;this.measurand=measurand;this.value=value;this.unit=unit;this.phase=phase;this.context=context;this.location=location;sampledAt=sampled;receivedAt=Instant.now();}public UUID getId(){return id;}public UUID getTenantId(){return tenantId;}public UUID getChargerId(){return chargerId;}public UUID getConnectorId(){return connectorId;}public UUID getSessionId(){return sessionId;}public String getTransactionId(){return transactionId;}public String getMeasurand(){return measurand;}public BigDecimal getValue(){return value;}public String getUnit(){return unit;}public String getPhase(){return phase;}public String getContext(){return context;}public String getLocation(){return location;}public Instant getSampledAt(){return sampledAt;}public Instant getReceivedAt(){return receivedAt;}}
